select json_build_object('linhas',(select count(*) from public.fin_lancamentos where origem_id like 'emprestimo-2026-11-%'),'principal_pago',(select sum(valor_bruto) from public.fin_lancamentos where origem_id ~ '^emprestimo-2026-11-p[0-9]+$'),'juros',(select sum(valor_bruto) from public.fin_lancamentos where origem_id like 'emprestimo-2026-11-p%-juros'),'parcela_01',(select sum(valor_bruto) from public.fin_lancamentos where origem_id in ('emprestimo-2026-11-p01','emprestimo-2026-11-p01-juros')),'parcela_48',(select sum(valor_bruto) from public.fin_lancamentos where origem_id in ('emprestimo-2026-11-p48','emprestimo-2026-11-p48-juros')));
